import { daysBetween } from './dates.js';
import { balanceDue } from './payments.js';
import { lineTotal, discount, vat } from './invoices.js';

/**
 * Get a list of overdue invoices.
 * @param {Array<any>} invoices
 * @param {string} asOf - Cutoff date in YYYY-MM-DD format
 * @returns {Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }>}
 */
export function overdueInvoices(invoices, asOf) {
  return invoices
    .filter(
      (invoice) =>
        (invoice.status === 'issued' || invoice.status === 'partially_paid') &&
        invoice.dueDate &&
        invoice.dueDate < asOf
    )
    .map((invoice) => ({
      number: invoice.number,
      customerId: invoice.customerId,
      dueDate: invoice.dueDate,
      daysOverdue: daysBetween(invoice.dueDate, asOf),
      due: balanceDue(invoice),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);
}

/**
 * Get a VAT summary across invoices.
 * @param {Array<any>} invoices
 * @returns {Array<{ rate: number, base: number, vat: number }>}
 */
export function vatSummary(invoices) {
  const summaryByRate = new Map();

  invoices
    .filter(
      (invoice) =>
        invoice.status === 'issued' ||
        invoice.status === 'partially_paid' ||
        invoice.status === 'paid'
    )
    .forEach((invoice) => {
      invoice.lines.forEach((line) => {
        const rate = line.vatRate;
        const lineTotal_ = lineTotal(line);
        const discountAmount = discount(line);
        const base = lineTotal_ - discountAmount;
        const vatAmount = vat(line);

        if (!summaryByRate.has(rate)) {
          summaryByRate.set(rate, { rate, base: 0, vat: 0 });
        }

        const entry = summaryByRate.get(rate);
        entry.base += base;
        entry.vat += vatAmount;
      });
    });

  return Array.from(summaryByRate.values()).sort((a, b) => b.rate - a.rate);
}

