  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  const i1 = issueInvoice(r1.value, []);

  const fee1 = lateFee(i1.value, '2026-09-16');
  const fee10 = lateFee(i1.value, '2026-09-25');

  assert(fee10 > fee1);
});

test('lateFee on partially paid invoice uses remaining balance', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 0 }],
    terms: 'NET14',
  });

  const i1 = issueInvoice(r1.value, []);
  const totals = invoiceTotals(i1.value);
  const p1 = recordPayment(i1.value, { amount: Math.floor(totals.total / 2), date: '2026-09-10' });

  assert.equal(p1.ok, true);
  const fee = lateFee(p1.value, '2026-09-30');

  const expectedDue = totals.total - Math.floor(totals.total / 2);
  const expectedFee = Math.round(expectedDue * 16 * 4 / 10000);
  assert(Math.abs(fee - expectedFee) <= 1);
});
